// P9-1 frozen evidence contract (types only, no UI).
//
// The frontend consumes curated frozen evidence from
// `@/data/models.v1.json` and `@/data/about.v1.json` (generated by
// `scripts/build_phase9_evidence.py`, READ-ONLY over frozen artifacts).
// Components must not infer science: every semantic is an explicit
// union below, and `validateModelsEvidence` / `validateAboutEvidence`
// fail closed on contract drift.

export const MODEL_EVIDENCE_CONTRACT_VERSION = "v1";
export const ABOUT_EVIDENCE_CONTRACT_VERSION = "v1";

export type MetricRole = "PRIMARY" | "SECONDARY" | "TECHNICAL";
export type MetricDirection = "lower_is_better" | "higher_is_better";
export type ProbabilitySemantics =
  | "INDEPENDENT_BINARY"
  | "MUTUALLY_EXCLUSIVE_FREQUENCY";
export type EvaluationClass =
  | "FROZEN_ONE_SHOT_2025_HOLDOUT"
  | "FROZEN_DEVELOPMENT_FOLDS"
  | "FROZEN_DEVELOPMENT_CALIBRATION";
export type SystemSemanticId = "FACT" | "PREDICTION" | "SIMULATION" | "STRATEGY";
export type CapabilityStatus = "FROZEN";

export interface EvidenceSource {
  path: string;
  sha256?: string;
  note: string;
}

export interface ModelSpec {
  task: "winner";
  target: string;
  eligibility: string;
  estimator: string;
  C: number;
  penalty: string;
  solver: string;
  max_iter: number;
  class_weight: null;
  random_state: number;
  feature_set: "ALL_84";
  feature_version: string;
  canonical_feature_count: number;
  transformed_feature_count: number;
  calibration: "RAW";
  probability_semantics: "INDEPENDENT_BINARY";
  final_fit_seasons: string;
  holdout_season: number;
  source_ids: string[];
}

export interface MetricRecord {
  id: string;
  display_name: string;
  value: number;
  direction: MetricDirection;
  role: MetricRole;
  aggregation: string;
  population: string;
  description: string;
  limitation: string;
  source_ids: string[];
}

export interface FoldLoss {
  mean: number;
  per_fold: { D1: number; D2: number; D3: number };
}

export interface DevelopmentCandidate {
  family: string;
  variant: string;
  source_ids: string[];
  development_log_loss: FoldLoss;
  limitation: string;
}

export interface ModelsEvidence {
  contract_version: "v1";
  sources: Record<string, EvidenceSource>;
  provenance: Record<string, string>;
  model_spec: ModelSpec;
  holdout_evidence: {
    evaluation_class: "FROZEN_ONE_SHOT_2025_HOLDOUT";
    population: {
      seasons: number[];
      races: number;
      eligible_states: number;
      positives: number;
      eligibility_mask: string;
    };
    aggregation: string;
    metrics: MetricRecord[];
    stages: { stage: string; race_macro_log_loss: number; definition: string }[];
    source_ids: string[];
  };
  temporal_evaluation: {
    protocol: string;
    development_folds: {
      fold: string;
      train: string;
      validate: number;
      train_states: number;
      val_states: number;
    }[];
    final_fit: string;
    holdout: number;
    guards: string[];
    source_ids: string[];
  };
  development_evidence: {
    evaluation_class: "FROZEN_DEVELOPMENT_FOLDS";
    protocol: string;
    aggregation: string;
    metric: string;
    candidates: DevelopmentCandidate[];
    warning: string;
    source_ids: string[];
  };
  model_selection: {
    serving_choice: string;
    selection_rule: string;
    measured_evidence: string[];
    engineering_context: string;
    limitations: string;
    source_ids: string[];
  };
  calibration_evidence: {
    evaluation_class: "FROZEN_DEVELOPMENT_CALIBRATION";
    population: string;
    metric: string;
    selection_rule: string;
    selected_method: "RAW";
    methods: Record<string, FoldLoss>;
    source_ids: string[];
  };
  feature_system: {
    canonical_total: number;
    transformed_dim: number;
    families: { family: string; count: number; meaning: string }[];
    feature_names_by_family: Record<string, string[]>;
    preprocessing: string;
    source_ids: string[];
  };
  coefficient_evidence: {
    explanation_space: "LOG_ODDS";
    intercept: number;
    reading: string;
    top_by_abs: {
      transformed: string;
      canonical: string;
      family: string;
      coefficient: number;
    }[];
    source_ids: string[];
  };
  permutation_evidence: {
    evidence_class: "PRE_2025_FINAL_FIT_IN_SAMPLE";
    evidence_class_note: string;
    metric: string;
    permutation_unit: string;
    repeats: number;
    base_seed: number;
    baseline_metric: number;
    entries: {
      canonical: string;
      family: string;
      mean_delta: number;
      min_delta: number;
      max_delta: number;
    }[];
    limitations: string;
    source_ids: string[];
  };
  temporal_safeguards: {
    statement: string;
    items: {
      id: string;
      title: string;
      description: string;
      source_ids: string[];
    }[];
  };
  performance: Record<
    string,
    {
      metric: string;
      value: number;
      scope: string;
      limitation: string;
      source_ids: string[];
    }[]
  >;
  limitations: { id: string; text: string }[];
}

export interface AboutEvidence {
  contract_version: "v1";
  sources: Record<string, EvidenceSource>;
  provenance: Record<string, string>;
  capabilities: {
    id: string;
    name: string;
    phase: number;
    status: CapabilityStatus;
    does: string;
    does_not: string;
    semantics: string;
    source_ids: string[];
  }[];
  system_semantics: {
    id: SystemSemanticId;
    display_name: string;
    definition: string;
    probability_semantics?: ProbabilitySemantics;
    not_to_confuse_with: SystemSemanticId[];
  }[];
  architecture: {
    implemented: string[];
    not_used: string[];
  };
  dataset_statistics: {
    tier_a: Record<string, number | string>;
    tier_b: Record<string, number | string>;
    phase2: Record<string, number | string>;
    replay: Record<string, number | string>;
    serving_scope_note: string;
  };
  reproducibility: {
    freeze_tags: string[];
    artifact_hashes: Record<string, string>;
    deterministic_seeds: number[];
    manifests: string[];
    make_targets: string[];
    note: string;
  };
  limitations: { id: string; text: string }[];
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function requireSources(sources: unknown): asserts sources is Record<string, EvidenceSource> {
  if (!isRecord(sources)) throw new Error("sources must be an object");
  for (const [key, entry] of Object.entries(sources)) {
    if (!isRecord(entry) || typeof entry["path"] !== "string") {
      throw new Error(`source ${key} must carry a path`);
    }
    if (typeof entry["path"] !== "string" || entry["path"].startsWith("/")) {
      throw new Error(`source ${key} path must be relative`);
    }
  }
}

function checkSourceIds(
  ids: unknown,
  sources: Record<string, EvidenceSource>,
  where: string,
): void {
  if (!Array.isArray(ids) || ids.length === 0) {
    throw new Error(`${where} must carry non-empty source_ids`);
  }
  for (const id of ids) {
    if (typeof id !== "string" || !(id in sources)) {
      throw new Error(`${where} references unknown source ${String(id)}`);
    }
  }
}

const ROLES: MetricRole[] = ["PRIMARY", "SECONDARY", "TECHNICAL"];

export function validateModelsEvidence(data: unknown): ModelsEvidence {
  if (!isRecord(data)) throw new Error("models evidence must be an object");
  if (data["contract_version"] !== MODEL_EVIDENCE_CONTRACT_VERSION) {
    throw new Error("models contract version mismatch");
  }
  requireSources(data["sources"]);
  const sources = data["sources"] as Record<string, EvidenceSource>;
  if (!isRecord(data["model_spec"])) throw new Error("model_spec missing");
  const spec = data["model_spec"] as Record<string, unknown>;
  if (spec["estimator"] !== "LogisticRegression") throw new Error("estimator drift");
  if (spec["C"] !== 0.01) throw new Error("C drift");
  if (spec["feature_set"] !== "ALL_84") throw new Error("feature set drift");
  if (spec["calibration"] !== "RAW") throw new Error("calibration drift");
  if (spec["probability_semantics"] !== "INDEPENDENT_BINARY") {
    throw new Error("probability semantics drift");
  }
  if (spec["canonical_feature_count"] !== 84) throw new Error("ALL_84 count drift");
  if (spec["transformed_feature_count"] !== 106) throw new Error("106-dim drift");
  if (!isRecord(data["holdout_evidence"])) throw new Error("holdout_evidence missing");
  const holdout = data["holdout_evidence"] as Record<string, unknown>;
  if (holdout["evaluation_class"] !== "FROZEN_ONE_SHOT_2025_HOLDOUT") {
    throw new Error("holdout class drift");
  }
  if (!Array.isArray(holdout["metrics"]) || holdout["metrics"].length === 0) {
    throw new Error("holdout metrics missing");
  }
  for (const metric of holdout["metrics"] as unknown[]) {
    if (!isRecord(metric) || typeof metric["value"] !== "number") {
      throw new Error("holdout metric must carry a numeric value");
    }
    if (!ROLES.includes(metric["role"] as MetricRole)) {
      throw new Error(`unknown metric role ${String(metric["role"])}`);
    }
    checkSourceIds(metric["source_ids"], sources, `metric ${String(metric["id"])}`);
  }
  if (!isRecord(data["development_evidence"])) {
    throw new Error("development_evidence missing");
  }
  const dev = data["development_evidence"] as Record<string, unknown>;
  if (dev["evaluation_class"] !== "FROZEN_DEVELOPMENT_FOLDS") {
    throw new Error("development class drift");
  }
  if (Object.keys(dev).some((key) => key === "holdout")) {
    throw new Error("development evidence must not embed holdout");
  }
  if (!isRecord(data["calibration_evidence"])) {
    throw new Error("calibration_evidence missing");
  }
  const cal = data["calibration_evidence"] as Record<string, unknown>;
  if (cal["evaluation_class"] !== "FROZEN_DEVELOPMENT_CALIBRATION") {
    throw new Error("calibration class drift");
  }
  if (cal["selected_method"] !== "RAW") throw new Error("calibration selection drift");
  if (!isRecord(data["permutation_evidence"])) {
    throw new Error("permutation_evidence missing");
  }
  const perm = data["permutation_evidence"] as Record<string, unknown>;
  if (perm["evidence_class"] !== "PRE_2025_FINAL_FIT_IN_SAMPLE") {
    throw new Error("permutation evidence class drift");
  }
  return data as unknown as ModelsEvidence;
}

export function validateAboutEvidence(data: unknown): AboutEvidence {
  if (!isRecord(data)) throw new Error("about evidence must be an object");
  if (data["contract_version"] !== ABOUT_EVIDENCE_CONTRACT_VERSION) {
    throw new Error("about contract version mismatch");
  }
  requireSources(data["sources"]);
  if (!Array.isArray(data["capabilities"]) || data["capabilities"].length === 0) {
    throw new Error("capabilities missing");
  }
  if (!Array.isArray(data["system_semantics"])) {
    throw new Error("system_semantics missing");
  }
  const ids = new Set(
    (data["system_semantics"] as unknown[]).map((entry) =>
      isRecord(entry) ? String(entry["id"]) : "",
    ),
  );
  for (const want of ["FACT", "PREDICTION", "SIMULATION", "STRATEGY"]) {
    if (!ids.has(want)) throw new Error(`system semantic ${want} missing`);
  }
  return data as unknown as AboutEvidence;
}
